{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "It would define an “authorizer” as a local board of education, the Tennessee Public Charter School Commission, or the Achievement School District when it makes decisions on charter applications and agreements.",
      "rationale": "Identifies the eligible entities but does not specify approval, renewal, and revocation as the decisions defining their authorizer role."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "It would also define “replication” as creating one or more charter schools with the same academic focus as an existing school operated by the same sponsor or governing body.",
      "rationale": "Conveys the definition's substantive elements; the summary separately describes the replication process."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "A sponsor seeking to open a new charter school generally would apply to the local board, unless the law allows a direct application to the commission.",
      "rationale": "Conveys the local-board application requirement and the condition for applying directly to the commission."
    },
    {
      "proposition_id": "P4",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The generic reference to shifting responsibilities does not identify the replacement in § 49-13-107(a)."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The commission would have to post letters of intent it receives within 10 days.",
      "rationale": "Conveys the commission's posting duty and the ten-day receipt-based deadline."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "A sponsor seeking to open a new charter school generally would apply to the local board, unless the law allows a direct application to the commission. Applications would use a form developed by the State Board of Education with the commission, be filed by February 1 of the year before the planned opening, and be reported by the authorizer to the commission within 10 days.",
      "rationale": "Conveys who applies, the filing destination, the deadline, and joint development of the application form."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Applications would use a form developed by the State Board of Education with the commission, be filed by February 1 of the year before the planned opening, and be reported by the authorizer to the commission within 10 days.",
      "rationale": "Conveys the authorizer's duty to report applications to the commission within ten days."
    },
    {
      "proposition_id": "P8",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention deletion of § 49-13-108(b)(4)."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "changes the stated start dates in two provisions to January 1, 2021.",
      "rationale": "States the new date but does not identify § 49-13-108(b)(5) or the repeal-triggered language being replaced."
    },
    {
      "proposition_id": "P10",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the agency-reference replacement in § 49-13-108(b)(5)(D)."
    },
    {
      "proposition_id": "P11",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe adding the commission alongside the department in § 49-13-108(g)."
    },
    {
      "proposition_id": "P12",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention limiting the applicability language to subsections (b)-(d)."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "Beginning July 1, 2025, if the commission overturns a local board’s denial of an application three times within three consecutive years, sponsors seeking to open schools in that district could apply directly to the commission for the following five years.",
      "rationale": "Conveys the effective date, three-overturn trigger, district limitation, and ensuing five-year direct-application window."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "The commission would have 90 days to decide each completed application; if it did not act, the application would be approved.",
      "rationale": "Conveys the decision deadline and deemed approval but omits the requirement to act by resolution at a regular or specially called meeting."
    },
    {
      "proposition_id": "P15",
      "status": "partial",
      "summary_quote": "After a denial, the sponsor could submit a corrected application within 30 days, and the commission would have 60 days to decide it; inaction would mean approval.",
      "rationale": "Conveys amendment and decision deadlines and deemed approval, but omits written, objective denial grounds and the receipt-based trigger for the sponsor's deadline."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "an approved school would have the commission as its authorizer and local education agency.",
      "rationale": "Conveys both roles the commission assumes upon approval."
    },
    {
      "proposition_id": "P17",
      "status": "full",
      "summary_quote": "The commission’s decisions would be final",
      "rationale": "Conveys finality of decisions under this direct-application process."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "After the five-year period, applications would again go to the local board unless the three-denial condition occurs again.",
      "rationale": "In context, conveys return to local-board applications unless the previously described overturning condition recurs."
    },
    {
      "proposition_id": "P19",
      "status": "partial",
      "summary_quote": "Public institutions of higher education could also apply to a local board or directly to the commission.",
      "rationale": "Conveys both application options but omits the restriction to public institutions in Tennessee."
    },
    {
      "proposition_id": "P20",
      "status": "partial",
      "summary_quote": "Public institutions of higher education could also apply to a local board or directly to the commission. A school they sponsor could give an enrollment preference to children of the institution’s employees or governing-body members, up to 25 percent of total enrollment.",
      "rationale": "Conveys the preference, eligible children, and enrollment cap but omits the Tennessee-institution limitation."
    },
    {
      "proposition_id": "P21",
      "status": "full",
      "summary_quote": "A governing body could petition its authorizer to change a charter agreement or to end it voluntarily before expiration; the commission would set the timelines and appeal process for amendment requests, and its denial of an amendment could not be appealed when it is the authorizer.",
      "rationale": "Conveys the petition authority, commission control of timelines and appeals, and the bar on appeals when the commission is authorizer."
    },
    {
      "proposition_id": "P22",
      "status": "full",
      "summary_quote": "A governing body could petition its authorizer to change a charter agreement or to end it voluntarily before expiration",
      "rationale": "Conveys the governing body's ability to petition for voluntary termination before expiration."
    },
    {
      "proposition_id": "P23",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Repealing § 49-13-142 does not itself describe removing its referenced exception from § 49-13-111(a)(4)."
    },
    {
      "proposition_id": "P24",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the replacement of department with state board in § 49-13-116(a)."
    },
    {
      "proposition_id": "P25",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the agency-reference replacement in § 49-13-116(b)."
    },
    {
      "proposition_id": "P26",
      "status": "partial",
      "summary_quote": "The commission would annually publish certain information described in the bill.",
      "rationale": "Conveys an annual publication duty but does not identify the information in § 49-13-116(b) or specify website publication."
    },
    {
      "proposition_id": "P27",
      "status": "partial",
      "summary_quote": "The bill would require the education commissioner to prepare an annual report on charter-school enrollment, geographic distribution, and performance.",
      "rationale": "Conveys the actor, frequency, and topics but omits that performance must be evidenced by the required school performance reports."
    },
    {
      "proposition_id": "P28",
      "status": "partial",
      "summary_quote": "By January 1 each year, each authorizer would have to submit and publish a report listing its schools’ operating status, oversight and contracted services, and performance reports.",
      "rationale": "Omits submission to the state board, website publication, required status categories and explanations, and use of each charter agreement's performance framework."
    },
    {
      "proposition_id": "P29",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the replacement in § 49-13-121(a) or its commission-consultation requirement."
    },
    {
      "proposition_id": "P30",
      "status": "full",
      "summary_quote": "The bill would require each authorizer to report renewal applications to the commission within 10 days.",
      "rationale": "Conveys the authorizer's reporting duty, recipient, and deadline."
    },
    {
      "proposition_id": "P31",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe replacing progress reports with authorizing report in § 49-13-121(d)."
    },
    {
      "proposition_id": "P32",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention deletion of § 49-13-121(e)."
    },
    {
      "proposition_id": "P33",
      "status": "partial",
      "summary_quote": "changes the stated start dates in two provisions to January 1, 2021.",
      "rationale": "States the replacement date but does not identify § 49-13-121(f) or the repeal-triggered language being replaced."
    },
    {
      "proposition_id": "P34",
      "status": "partial",
      "summary_quote": "If the commission approves a renewal after overturning a local board’s decision, or under specified provisions of state law, the renewed agreement would last from five to ten academic years, with the commission setting the term by resolution.",
      "rationale": "Conveys the appeal-related trigger and term requirements but does not say the school and commission must enter into the renewed agreement."
    },
    {
      "proposition_id": "P35",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify adding the commission alongside the department in § 49-13-121(i)."
    },
    {
      "proposition_id": "P36",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the agency-reference replacement in § 49-13-121(k)."
    },
    {
      "proposition_id": "P37",
      "status": "partial",
      "summary_quote": "If the commission approves a renewal after overturning a local board’s decision, or under specified provisions of state law, the renewed agreement would last from five to ten academic years, with the commission setting the term by resolution.",
      "rationale": "Conveys the term rule but leaves the qualifying renewal provisions unidentified and omits the required agreement between the school and commission."
    },
    {
      "proposition_id": "P38",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe adding the commission alongside the department in § 49-13-122(g)."
    },
    {
      "proposition_id": "P39",
      "status": "full",
      "summary_quote": "By December 1, each local education agency collecting authorizer fees would report the previous school year’s fees and the authorizing work paid for with those fees to the State Board",
      "rationale": "Conveys the covered LEAs, reporting deadline, recipient, reporting period, and required fee-and-use information."
    },
    {
      "proposition_id": "P40",
      "status": "partial",
      "summary_quote": "the State Board would post the information by December 11.",
      "rationale": "Conveys the posting deadline but omits the state board's duty to create a standard report template."
    },
    {
      "proposition_id": "P41",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the replacement in § 49-13-133(b)."
    },
    {
      "proposition_id": "P42",
      "status": "full",
      "summary_quote": "repeals section 49-13-142",
      "rationale": "Identifies the repealed section precisely."
    },
    {
      "proposition_id": "P43",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Mentioning the state board's model framework does not describe replacing every department reference in § 49-13-143(a)."
    },
    {
      "proposition_id": "P44",
      "status": "full",
      "summary_quote": "An authorizer that has not adopted a performance framework for all its schools would have to use the State Board’s model framework.",
      "rationale": "Conveys the triggering condition and mandatory use of the state board's model framework."
    },
    {
      "proposition_id": "P45",
      "status": "partial",
      "summary_quote": "A governing body could seek to replicate a school in the district where it already operates if at least one of its charter schools had operated for a full school year when it submitted its letter of intent. It could apply to the local board or directly to the commission.",
      "rationale": "Conveys the operating-history, timing, geographic, and application-route requirements but omits that the qualifying school must be authorized by a local board or the commission."
    },
    {
      "proposition_id": "P46",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe the separate duty to develop a replication application form in consultation with the commission."
    },
    {
      "proposition_id": "P47",
      "status": "partial",
      "summary_quote": "Direct commission applications would follow the same deadlines, correction process, and final-decision rules described above.",
      "rationale": "Incorporates the earlier 90-day decision and deemed-approval rules but omits action by resolution at a regular or specially called meeting."
    },
    {
      "proposition_id": "P48",
      "status": "partial",
      "summary_quote": "Direct commission applications would follow the same deadlines, correction process, and final-decision rules described above.",
      "rationale": "Incorporates the earlier correction deadlines and deemed approval, but the summary never supplies written, objective denial grounds or the receipt-based trigger for amendment."
    },
    {
      "proposition_id": "P49",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The replication paragraph incorporates deadlines, correction procedures, and finality, but does not extend the commission's authorizer and LEA roles to approved replications."
    },
    {
      "proposition_id": "P50",
      "status": "full",
      "summary_quote": "Direct commission applications would follow the same deadlines, correction process, and final-decision rules described above.",
      "rationale": "Expressly applies the previously stated finality rule to direct replication applications."
    },
    {
      "proposition_id": "P51",
      "status": "full",
      "summary_quote": "It could apply to the local board or directly to the commission.",
      "rationale": "In the replication paragraph, expressly preserves the governing body's local-board application option."
    },
    {
      "proposition_id": "P52",
      "status": "full",
      "summary_quote": "The bill itself would take effect July 1, 2025.",
      "rationale": "States the act's effective date accurately."
    }
  ]
}
